import sys
stdin = sys.stdin.readline
stdout = sys.stdout.write

def next_int(): return int(stdin().strip())
def next_array(): return list(map(int, stdin().split()))

def solve():
    h, w, m = next_array()
    color_count = {}
    ops = []
    for i in range(m):
        t, a, x = next_array()
        ops.append([t, a - 1, x])

    row_visited = [False] * h
    col_visited = [False] * w
    r = h
    c = w

    for i in range(m - 1, -1, -1):
        t, a, x = ops[i]
        if t == 1:
            if not row_visited[a]:
                row_visited[a] = True
                color_count[x] = color_count.get(x, 0) + c
                r -= 1
        elif t == 2:
            if not col_visited[a]:
                col_visited[a] = True
                color_count[x] = color_count.get(x, 0) + r
                c -= 1

    unique_colors = [(color, count) for color, count in color_count.items() if count > 0]
    print(len(unique_colors))
    for color, count in unique_colors:
        print(f"{color} {count}")

if __name__ == "__main__":
    solve()
